                <p className="text-sm leading-relaxed">{message.content}</p>
                <p className={`text-xs mt-1 ${
                  message.sender === "user" ? "text-gray-500" : "text-white/70"
                }`}>{formatTime(message.timestamp)}</p>

                {/* Outfit Cards */}
                {message.outfits && message.outfits.length > 0 && (
                  <div className="mt-3 space-y-3">
                    {message.outfits.map((outfit) => (
                      <Card key={outfit.id} className="p-3 bg-white/20 backdrop-blur-sm">
                        <div className="flex gap-3">
                          <img
                            src={outfit.imageUrl || "/placeholder.svg?height=80&width=80"}
                            alt={outfit.title}
                            className="w-20 h-20 rounded-lg object-cover"
                          />
                          <div className="flex-1 min-w-0">
                            <h4 className="font-semibold text-sm text-balance text-white">{outfit.title}</h4>
                            <p className="text-xs text-white/70 text-pretty mt-1">{outfit.description}</p>
                            <div className="flex items-center justify-between mt-2">
                              <span className="text-sm font-bold text-white">฿{outfit.totalPrice.toLocaleString()}</span>
                              <Button size="sm" className="h-7 px-3 text-xs bg-white text-primary hover:bg-white/90" onClick={() => {
                                onOutfitSelect?.(outfit.id);
                                onViewDetails?.(outfit);
                              }}>
                                View Details
                              </Button>
                            </div>
                          </div>
                        </div>
                      </Card>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}

        {/* Typing Indicator */}
        {isTyping && (
          <div className="flex justify-start animate-fade-in-up">
            <div className="flex items-start gap-3">
              <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center flex-shrink-0 mt-1">
                <Sparkles className="w-4 h-4 text-white" />
              </div>
              <div className="bg-primary rounded-2xl px-4 py-3">
                <div className="flex items-center space-x-1">
                  <div className="flex space-x-1">
                    <div className="w-2 h-2 bg-white/70 rounded-full animate-typing"></div>
                    <div
                      className="w-2 h-2 bg-white/70 rounded-full animate-typing"
                      style={{ animationDelay: "0.2s" }}
                    ></div>
                    <div
                      className="w-2 h-2 bg-white/70 rounded-full animate-typing"
                      style={{ animationDelay: "0.4s" }}
                    ></div>
                  </div>
                  <span className="text-xs text-white/70 ml-2">AI is thinking...</span>
                </div>
              </div>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>
      )}

      {/* Quick Actions */}
      {!testMode && messages.length > 0 && (
        <div className="px-4 py-2">
          <div className="flex gap-2 overflow-x-auto pb-2">
            {quickActions.map((action) => (
              <Button
                key={action}
                variant="outline"
                size="sm"
                className="whitespace-nowrap flex-shrink-0 bg-gray-50 rounded-full border border-gray-200 hover:bg-gray-100 transition-colors"
                onClick={() => handleQuickAction(action)}
              >
                <span className="text-xs font-medium">{action}</span>
              </Button>
            ))}
          </div>
        </div>
      )}

      {/* Input Area */}
      {!testMode && (
      <div className="border-t bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">
        <div className="flex items-end gap-2 p-4">
          <div className="flex-1 relative">
            <Input
              ref={inputRef}
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder="Ask me what to wear..."
              className="pr-12 min-h-[44px] resize-none rounded-full"
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault()
                  handleSendMessage(inputValue)
                }
              }}
            />
            <Button
              size="sm"
              variant="ghost"
              className="absolute right-1 top-1/2 -translate-y-1/2 h-8 w-8 p-0 rounded-full"
              disabled
            >
              <Camera className="w-4 h-4" />
            </Button>
          </div>
          <Button
            size="sm"
            className="h-11 w-11 rounded-full p-0"
            onClick={() => handleSendMessage(inputValue)}
            disabled={!inputValue.trim() || isTyping}
          >
            <Send className="w-4 h-4" />
          </Button>
        </div>
      </div>
      )}
    </div>
  )
}

/**
 * Chat API Route
 * Handles AI-powered fashion recommendations
 */

import { NextRequest, NextResponse } from 'next/server'
import type { EnhancedProduct } from '@/lib/types/product-types'
import { loadProductsServerSide } from '@/lib/server-product-loader'
import {
  processAIChatRequest,
  getFallbackRecommendations,
  type ChatRequest,
} from '@/lib/services/ai-chat-service'
import { generateOutfitsFromQuery } from '@/lib/enhanced-outfit-generator'
import { getProductName, getProductPrice, getProductImageUrl } from '@/lib/utils/product-utils'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const { message, userPreferences, conversationHistory, sessionContext, conversationId } = body

    if (!message || typeof message !== 'string') {
      return NextResponse.json({ error: 'Message is required' }, { status: 400 })
    }

    console.log('[Chat API] Processing message:', message)

    // Log session context if provided (v2.0 feature)
    if (sessionContext) {
      console.log(`[Chat API] Session has ${sessionContext.recommendedProductIds?.length || 0} previously recommended products`)
    }

    // Load enhanced products (server-side)
    const products = await loadProductsServerSide()

    if (products.length === 0) {
      console.warn('[Chat API] No enhanced products available')
      return NextResponse.json(
        {
          message: 'ขออภัยค่ะ ระบบกำลังโหลดข้อมูลสินค้า กรุณาลองใหม่อีกครั้งค่ะ',
          outfits: [],
        },
        { status: 200 }
      )
    }

    console.log(`[Chat API] Using ${products.length} enhanced products`)

    // Check if AI is enabled
    const useAI = process.env.OPENROUTER_API_KEY !== undefined

    let response

    if (useAI) {
      // Use AI-powered recommendations
      console.log('[Chat API] Using AI-powered recommendations')

      const chatRequest: ChatRequest = {
        message,
        userPreferences,
        conversationHistory,
        sessionContext, // v2.0: Include session context for duplicate prevention
        conversationId, // v2.0: Include conversation ID for session tracking
      }

      response = await processAIChatRequest(chatRequest, products)
    } else {
      // Use rule-based fallback
      console.log('[Chat API] Using rule-based recommendations (no AI key)')

      const chatRequest: ChatRequest = {
        message,
        userPreferences,
        sessionContext, // v2.0: Include session context even for fallback
        conversationId, // v2.0: Include conversation ID
      }

      response = getFallbackRecommendations(chatRequest, products)
    }

    // Generate outfits from recommended products
    const outfits = generateOutfitsFromQuery(response.recommendedProducts || products, message, 5)

    console.log(`[Chat API] Generated ${outfits.length} outfits`)

    // Convert outfits to response format
    const outfitResponses = outfits.map((outfit) => ({
      id: outfit.id,
      title: outfit.title,
      description: outfit.description,
      totalPrice: outfit.totalPrice,
      items: outfit.products.map((product) => ({
        sku: product.sku,
        id: product.id,
        name: getProductName(product, 'th'),
        nameEn: getProductName(product, 'en'),
        brand: product.brand,
        price: getProductPrice(product),
        imageUrl: getProductImageUrl(product),
        onlineUrl: product.centralIntegration?.productUrl || '',
        category: product.classification?.category?.category || '',
        gender: product.classification?.gender || 'unisex',
        occasion: product.classification?.tags?.occasion || [],
        formality: product.style?.formalityLevel || 5,
        colors: [
          product.style?.colors?.primary || 'unknown',
          ...(product.style?.colors?.secondary || []),
        ].filter(Boolean),
        sizes: product.sizing?.availableSizes || [],
        availability: product.availability?.status || 'unknown',
      })),
      occasion: outfit.occasion,
      formality: outfit.formality,
      imageUrl: outfit.primaryImage,
    }))

    return NextResponse.json({
      message: response.message,
      outfits: outfitResponses,
      occasion: response.occasion,
      reasoning: response.reasoning,
      sessionContext: response.sessionContext, // v2.0: Return updated session context to client
    })
  } catch (error) {
    console.error('[Chat API] Error:', error)
    return NextResponse.json(
      {
        error: 'Failed to process chat request',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    )
  }
}
